INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente feminina, 42 anos, com história de asma grave e rinossinusite crônica, procura atendimento por dispneia, febre e dor torácica pleurítica à direita. O hemograma revela leucocitose com 22% de eosinófilos (2.500/mm³). A toracentese revela um exsudato com 45% de eosinófilos e pH de 7,30. Diante do quadro sistêmico e pleural, qual o diagnóstico mais provável?", "options": {"a": "Pneumonia por Strongyloides stercoralis com derrame reativo.", "b": "Síndrome de Löffler clássica.", "c": "Infarto pulmonar hemorrágico por tromboembolismo.", "d": "Granulomatose eosinofílica com poliangiite (Síndrome de Churg-Strauss).", "e": "Derrame pleural induzido pelo uso de montelucaste."}, "answer": "d", "rationale": "A Síndrome de Churg-Strauss (GEPA) é caracterizada pelo binômio asma grave + eosinofilia periférica marcada (> 1.500/mm³). O envolvimento pleural ocorre em cerca de 30% dos casos, tipicamente como um exsudato eosinofílico. O quadro de sinusite crônica e asma reforça FORTEMENTE este diagnóstico imuno-reumatológico.", "option_rationales": {"a": "Incorreta. Parasitoses podem dar eosinofilia, mas o quadro clínico de asma grave e sinusite aponta para vasculite.", "b": "Incorreta. A síndrome de Löffler é uma pneumonia eosinofílica autolimitada e migratória, raramente causando derrame pleural importante ou sinusite.", "c": "Incorreta. O TEP pode dar eosinofilia pleural leve, mas não explica a eosinofilia periférica grave e a asma/sinusite.", "d": "Correta. A tríade asma + eosinofilia + serosite (derrame) é clássica da GEPA.", "e": "Incorreta. Embora o montelucaste tenha sido associado ao surgimento de Churg-Strauss, a doença é a vasculite em si, não um efeito tóxico direto do remédio na pleura."}, "difficulty": "dificil", "tags": ["Pneumologia", "Vasculites", "Eosinofilia Pleural", "Churg-Strauss"]}', 150, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A biópsia pleural por agulha ''cega'' (Abrams) apresenta sensibilidade significativamente maior para o diagnóstico de qual patologia em comparação ao câncer pleural?", "options": {"a": "Sarcoidose.", "b": "Mesotelioma.", "c": "Adenocarcinoma metastático.", "d": "Tuberculose Pleural.", "e": "Linfoma."}, "answer": "d", "rationale": "A TB pleural acomete a pleura de forma difusa (granulomas em toda a superfície), o que dá à biópsia cega uma sensibilidade de 70-80%. Já o câncer pleural costuma acometer a pleura de forma nodular e focal, fazendo com que a biópsia cega ''erre'' o alvo frequentemente (sensibilidade de 40-50%).", "option_rationales": {"a": "Incorreta. Rara e de difícil captura na biópsia cega.", "b": "Incorreta. Exige biópsia dirigida por VATS pelo baixo rendimento da cega.", "c": "Incorreta. Citologia costuma ser melhor que biópsia cega.", "d": "Correta. Principal indicação de biópsia de Abrams/Cope.", "e": "Incorreta. Exige grande quantidade de tecido para arquitetura linfonodal."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Biópsia Pleural"]}', 151, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal função fisiológica da pleura visceral?", "options": {"a": "Filtrar o ar inspirado.", "b": "Produzir 90% do líquido pleural diário.", "c": "Absorver proteínas do espaço pleural.", "d": "Proteger o coração contra infecções bacterianas.", "e": "Facilitar o deslizamento pulmonar durante a respiração e manter a anatomia lobar através das cisuras."}, "answer": "e", "rationale": "A pleura visceral reveste o pulmão e permite o deslizamento suave contra a pleura parietal graças à fina camada de líquido pleural (lubrificante). Suas invaginações (cisuras) dividem os pulmões em lobos, garantindo a expansibilidade e limitando a propagação de patologias em alguns cenários.", "option_rationales": {"a": "Incorreta. Função do epitélio respiratório e cílios.", "b": "Incorreta. Produção é majoritariamente parietal.", "c": "Incorreta. Absorção é quase exclusiva da parietal via estomas linfáticos.", "d": "Incorreta. Função do pericárdio.", "e": "Correta. Função mecânica e anatômica fundamental."}, "difficulty": "facil", "tags": ["Pneumologia", "Anatomia", "Fisiologia"]}', 152, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de ácido hialurônico (hialuronato) no líquido pleural foi historicamente proposta como um marcador para qual neoplasia específica da pleura?", "options": {"a": "Linfoma de Burkitt.", "b": "Tumor Fibroso Solitário.", "c": "Mesotelioma Maligno.", "d": "Angiossarcoma.", "e": "Adenocarcinoma de pulmão."}, "answer": "c", "rationale": "Células mesoteliais malignas produzem grandes quantidades de ácido hialurônico. Valores > 100 mg/L no líquido pleural são muito sugestivos de mesotelioma, embora a técnica de dosagem não seja rotineiramente disponível em todos os laboratórios.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Marcador bioquímico clássico da biologia mesotelial.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Bioquímica", "Mesotelioma", "Marcadores"]}', 153, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de derrame pleural neutrofílico (PMN > 50%) em um paciente com dor abdominal aguda, febre e sinal de Murphy positivo aponta para qual diagnóstico?", "options": {"a": "Toxoplasmose.", "b": "Amiodarona.", "c": "Infarto Pulmonar.", "d": "Pleurite por TB.", "e": "Abcesso Subfrênico."}, "answer": "e", "rationale": "Qualquer processo inflamatório infradiafragmático (colecistite, abscesso hepático ou subfrênico) pode causar um ''derrame simpático'' por translocação de mediadores inflamatórios através dos linfáticos diafragmáticos. O líquido é exsudativo e predominantemente neutrofílico.", "option_rationales": {"a": "Incorreta. Manifestação pleural da toxo é rara e não tem Murphy.", "b": "Incorreta. Amiodarona causa derrame eosinofílico/linfocítico crônico.", "c": "Incorreta. Não explicaria o Murphy positivo.", "d": "Incorreta. TB é linfocítica.", "e": "Correta. Associação clássica da pleura com o abdome agudo infeccioso."}, "difficulty": "facil", "tags": ["Pneumologia", "Cirurgia", "Abdome Agudo", "Derrame Simpático"]}', 154, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No paciente com cirrose e derrame pleural bilateral, a ocorrência de febre e dor torácica deve levantar a suspeita de Pleurite Bacteriana Espontânea (SBPE). Qual o micro-organismo MAIS FREQUENTEMENTE isolado nesta condição?", "options": {"a": "Legionella pneumophila.", "b": "Staphylococcus aureus.", "c": "Escherichia coli.", "d": "Mycobacterium avium.", "e": "Pseudomonas aeruginosa."}, "answer": "c", "rationale": "Assim como na Peritonite Bacteriana Espontânea (PBE), a SBPE é causada majoritariamente por enterobactérias gram-negativas (E. coli, Klebsiella), resultantes da translocação bacteriana intestinal.", "option_rationales": {"a": "Incorreta. Causa de pneumonia comunitária grave, não de SBPE.", "b": "Incorreta. Mais comum em infecções de pele ou pós-procedimentos.", "c": "Correta. Agente clássico da translocação no cirrótico.", "d": "Incorreta. Germe oportunista raro.", "e": "Incorreta. Germe hospitalar, menos comum na SBPE comunitária pura."}, "difficulty": "media", "tags": ["Pneumologia", "Gastroenterologia", "Cirrose", "Infectologia"]}', 155, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Embolia Pulmonar (TEP) por radiografia de tórax, um achado característico é uma opacidade em forma de cunha, com base voltada para a pleura, localizada na periferia do pulmão. Qual o nome deste sinal?", "options": {"a": "Linhas B de Kerley.", "b": "Sinal da Silhueta.", "c": "Corcova de Hampton.", "d": "Sinal de Westermark.", "e": "Sinal de Palla."}, "answer": "c", "rationale": "A ''Corcova de Hampton'' (Hampton''s Hump) representa um infarto pulmonar hemorrágico na periferia. É um achado radiográfico raro, mas clássico do TEP. O sinal de Westermark é a oligoemia focal distal à embolia.", "option_rationales": {"a": "Incorreta. Sinal de congestão venocapilar pulmonar e edema intersticial.", "b": "Incorreta. Regra geral para localizar lesões intratorácicas.", "c": "Correta. Sinal clássico de infarto pulmonar periférico.", "d": "Incorreta. Reflete área de menor vascularização, não consolidação em cunha.", "e": "Incorreta. Reflete a dilatação da artéria pulmonar central por trombo."}, "difficulty": "facil", "tags": ["Pneumologia", "TEP", "Radiologia", "Sinais Clássicos"]}', 156, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Reumatoide'' é uma causa de exsudato crônico. Qual parâmetro laboratorial no líquido pleural da artrite reumatoide costuma apresentar valores extremamente ELEVADOS, muitas vezes superando os níveis séricos?", "options": {"a": "Triglicerídeos.", "b": "Glicose.", "c": "Células mesoteliais (> 20%).", "d": "Fator Reumatoide (FR).", "e": "Ph (alcalino)."}, "answer": "d", "rationale": "No derrame pleural da artrite reumatoide, os títulos de Fator Reumatoide no líquido são tipicamente maiores ou iguais aos títulos séricos (geralmente > 1:320). Além disso, a glicose é muito baixa e o LDH muito alto.", "option_rationales": {"a": "Incorreta. Sem relação direta, a menos que haja pseudoquilotórax associado.", "b": "Incorreta. Glicose é mínima por bloqueio de transporte.", "c": "Incorreta. As mesoteliais costumam ser raras por espessamento pleural.", "d": "Correta. Característica imunológica do derrame reumatoide.", "e": "Incorreta. Ph é ácido devido à intensa inflamação e glicólise."}, "difficulty": "media", "tags": ["Pneumologia", "Reumatologia", "Artrite Reumatoide", "FR"]}', 157, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal causa de hemotórax não traumático (espontâneo) em um adulto jovem previamente hígido, sem história de coagulopatia?", "options": {"a": "Câncer de pulmão oculto.", "b": "Malformação arteriovenosa pulmonar.", "c": "Perfuração de artéria intercostal por tosse vigorosa.", "d": "Ruptura de aneurisma de aorta descendente.", "e": "Pneumotórax espontâneo primário (ruptura de bridas vasculares pleurais durante o colapso pulmonar)."}, "answer": "e", "rationale": "O hemopneumotórax espontâneo ocorre em cerca de 1-5% dos casos de pneumotórax espontâneo primário. O sangramento ocorre geralmente pela ruptura de pequenas vasos ou bridas que ligam a pleura parietal à visceral durante o colapso do pulmão. Pode ser volumoso e exigir intervenção.", "option_rationales": {"a": "Incorreta. Muito improvável na faixa etária e perfil descrito.", "b": "Incorreta. A MAV pode causar hemoptise ou hemotórax, mas é menos frequente que a complicação do pneumotórax.", "c": "Incorreta. Muito raro sem trauma direto.", "d": "Incorreta. Causa de idosos hipertensos, não jovens hígidos.", "e": "Correta. Mecanismo clássico de hemotórax espontâneo no jovem."}, "difficulty": "media", "tags": ["Pneumologia", "Pneumotórax", "Hemotórax", "Urgências"]}', 158, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com Artrite Reumatoide, o derrame pleural tipicamente apresenta níveis MUITO BAIXOS de qual componente do complemento?", "options": {"a": "Apenas C9.", "b": "Não existe complemento no líquido pleural.", "c": "Apenas C1q.", "d": "O complemento está sempre elevado.", "e": "C3 e C4 ( níveis de complemento total CH50 frequentemente indetectáveis)."}, "answer": "e", "rationale": "O consumo de complemento no espaço pleural da Artrite Reumatoide é intenso devido à formação in situ de imunocomplexos. Isso ajuda a diferenciar da pleurite lúpica, onde o complemento também pode estar baixo, mas no reumatoide a queda é geralmente mais drástica e associada à glicose baixíssima.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta. Líquidos exsudativos têm proteínas do complemento.", "c": "Incorreta.", "d": "Incorreta. O consumo leva à redução.", "e": "Correta. Marcador de atividade inflamatória imune intensa local."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Artrite Reumatoide", "Complemento"]}', 159, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em qual das seguintes condições a pleura parietal apresenta tipicamente um aspecto de ''renda'' ou ''favas de mel'' na inspeção direta por videotoracoscopia?", "options": {"a": "Linfangiomatose pleuropulmonar difusa ou Linfangiomatose capilar.", "b": "Empiema bacteriano.", "c": "Início da Tuberculose Pleural.", "d": "Insuficiência Cardíaca pura.", "e": "Silicose aguda."}, "answer": "a", "rationale": "A proliferação anômala de canais linfáticos na pleura (linfangiomatose) cria um padrão reticular e multicístico visível macroscopicamente, frequentemente associado a derrames quilosos recorrentes.", "option_rationales": {"a": "Correta. Descrição morfológica de distúrbios linfáticos pleurais.", "b": "Incorreta. Pleura recoberta por fibrina amarelada.", "c": "Incorreta. TB dá nódulos esbranquiçados (grânulos de milho).", "d": "Incorreta. Pleura lisa.", "e": "Incorreta. Silicose atinge pouco a pleura isoladamente comparada ao pulmão."}, "difficulty": "dificil", "tags": ["Pneumologia", "Linfologia", "VATS", "Morfologia"]}', 160, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Xantomatose Pleural'' é um achado raro caracterizado por depósitos amarelos de gordura na pleura. Qual condição metabólica deve ser investigada?", "options": {"a": "Hipotireoidismo subclínico.", "b": "Diabetes Mellitus tipo 1.", "c": "Porfiria.", "d": "Hiperlipoproteinemias graves (geralmente tipo II ou III).", "e": "Doença de Wilson."}, "answer": "d", "rationale": "Xantomas são depósitos cutâneos ou viscerais de macrófagos carregados de colesterol. Na pleura, são raríssimos, mas indicam distúrbios severos do metabolismo lipídico sistêmico.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta.", "d": "Correta. Correlação metabólica-anatomopatológica.", "e": "Incorreta. Cobre."}, "difficulty": "dificil", "tags": ["Pneumologia", "Metabolismo", "Xantomatose", "Lipídios"]}', 161, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Considerando o Derrame Pleural Eosinofílico (Eosinófilos > 10% no líquido), qual das seguintes condições é considerada uma causa ''falsa'' ou secundária frequente por introdução de ar ou sangue no espaço pleural?", "options": {"a": "Pneumonia por Chlamydia psittaci.", "b": "Toracocentese prévia ou pneumotórax.", "c": "Sarcoidose em fase pulmonar avançada.", "d": "Síndrome de Churg-Strauss (Granulomatose Eosinofílica com Poliangiite).", "e": "Infestação por Strongyloides stercoralis."}, "answer": "b", "rationale": "A causa mais comum de eosinofilia pleural é a presença de ar (pneumotórax) ou sangue (hemotórax) no espaço pleural. Uma toracentese traumática ou prévia pode induzir eosinofilia reativa em procedimentos subsequentes, o que diminui o valor diagnóstico da eosinofilia para condições raras.", "option_rationales": {"a": "Incorreta. Causas infecciosas bacterianas raramente dão eosinofilia.", "b": "Correta. Ar e sangue são os principais estimulantes de eosinófilos na pleura.", "c": "Incorreta. Sarcoidose cursa com derrame linfocítico ou granulomatoso.", "d": "Incorreta. É uma causa real de eosinofilia pleural, mas muito rara comparada ao trauma/ar.", "e": "Incorreta. Parasitoses dão eosinofilia, mas são causas menos comuns que a iatrogenia."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Eosinofílico", "Etiologia"]}', 162, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição do Intervalo entre os batimentos no eletrocardiograma (Intervalo QT) pode sofrer interferência em qual tipo de derrame cavitário?", "options": {"a": "Derrame Pericárdico (mimetiza baixa voltagem, mas não altera o QT intrinsicamente, exceto por distúrbios de repolarização associados).", "b": "Apenas urinotórax.", "c": "Não há interferência do derrame pleural no ECG.", "d": "Derrame Pleural Bilateral volumoso.", "e": "Apenas derrame pleural esquerdo."}, "answer": "a", "rationale": "Embora o derrame pleural possa causar baixa voltagem nos complexos QRS, as alterações de tempo (QT) são raras e indiretas (ex: hipocalcemia no quilotórax ou hipocalemia). A questão foca na confusão clássica com a pericardite associada ( Dressler) que altera o segmento ST e a onda T.", "option_rationales": {"a": "Correta. Derrame pleural volumoso reduz a voltagem, mas o QT é alterado por serosites ou eletrólitos.", "b": "Incorreta.", "c": "Incorreta. Existe interferência na voltagem.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "ECG", "Derrame Pleural", "Interferências"]}', 163, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A pseudotumefação pleural (''Tumor Evanescente'' ou ''Tumor Fantasma'') é uma imagem radiológica que pode mimetizar um nódulo ou massa pulmonar sólida. Sobre esta condição, assinale a alternativa que descreve sua localização e etiologia clássicas.", "options": {"a": "Localizada no ângulo costofrênico posterior; etiologia associada à Neoplasia de Cólon.", "b": "Localizada na cisura horizontal ou oblíqua; etiologia associada à Insuficiência Cardíaca Congestiva.", "c": "Localizada no mediastino superior; etiologia associada ao Bócio Mergulhante.", "d": "Localizada no ápice pulmonar; etiologia associada à Tuberculose.", "e": "Localizada na pleura visceral do lobo inferior; etiologia associada ao Infarto Pulmonar."}, "answer": "b", "rationale": "O tumor fantasma é um derrame pleural loculado dentro de uma cisura (geralmente a horizontal), que assume aspecto de massa ao RX. Ele é típico da ICC e ''desaparece'' rapidamente após o início de terapia diurética agressiva, daí o nome.", "option_rationales": {"a": "Incorreta. A localização clássica é cisural.", "b": "Correta. Localização cisural + ICC é o quadro clínico-radiológico clássico.", "c": "Incorreta. Bócio é uma massa mediastinal, não pleural cisural.", "d": "Incorreta. O tumor fantasma não é apical nem tipicamente da TB.", "e": "Incorreta. Infarto pulmonar causa a ''Corcova de Hampton'' (imagem periférica em cunha)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Radiologia", "ICC", "Derrame Loculado"]}', 164, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Tuberculosa'' é classicamente descrita como uma resposta de hipersensibilidade retardada ao Mycobacterium tuberculosis. Por esse motivo, qual dos seguintes achados microbiológicos no líquido pleural é o MAIS COMUM nesse tipo de derrame?", "options": {"a": "Coloração de prata (Grocott) positiva.", "b": "Cultura do líquido positiva em 90% dos casos.", "c": "Líquido pleural estéril (Cultura e BAAR negativos na maioria das vezes).", "d": "Presença de grânulos de enxofre.", "e": "Presença massiva de BAAR no sedimento (Gram de TB)."}, "answer": "c", "rationale": "Como a TB pleural é uma reação de hipersensibilidade mediada por linfócitos T a poucos antígenos bacilares no espaço pleural, a carga de bacilos no líquido é muito baixa. O BAAR é quase sempre negativo e a cultura do líquido é positiva em apenas 20-30% dos casos. O diagnóstico geralmente depende do ADA ou da biópsia pleural.", "option_rationales": {"a": "Incorreta. Usado para fungos.", "b": "Incorreta. Sensibilidade da cultura no líquido é baixa.", "c": "Correta. Padrão paucibacilar característico.", "d": "Incorreta. Clássico da Actinomicose.", "e": "Incorreta. BAAR positivo em líquido é raríssimo na TB pleural isolada (sugerindo ruptura de cavidade)."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Microbiologia", "Fisiopatologia"]}', 165, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A realização de ''Toracocentese repetida'' (Symphony of Thoracentesis) em pacientes com derrame neoplásico sem reexpansão pulmonar deve ser desencorajada em favor de qual conduta agressiva/definitiva?", "options": {"a": "Pneumonectomia de resgate.", "b": "Uso de doses altas de furosemida endovenosa.", "c": "Administração de quimioterapia intrapleural isolada.", "d": "Inserção de cateter pleural de demora (IPC).", "e": "Substituição do oxigênio por hélio."}, "answer": "d", "rationale": "Se o pulmão está encarcerado (não reexpande com a drenagem), a pleurodese química falhará e a toracentese repetida levará a multiloculações, empiema e desconforto crônico. O cateter de demora (IPC) permite a drenagem paliativa sem necessidade de sínfise pleural.", "option_rationales": {"a": "Incorreta. Extremamente agressivo e sem benefício paliativo em doença avançada.", "b": "Incorreta. Diuréticos não resolvem derrame neoplásico (exsudato).", "c": "Incorreta. Taxas de sucesso menores que IPC para controle de sintomas.", "d": "Correta. Melhor conduta para ''pulmão encarcerado'' sintomático.", "e": "Incorreta. Heliox não tem papel no derrame pleural."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Palhação", "Terapêutica"]}', 166, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com infecção pelo vírus HIV, a ocorrência de derrame pleural por Sarcoma de Kaposi apresenta qual característica do líquido?", "options": {"a": "Transudato amarelo citrino.", "b": "Exsudato tipicamente hemorrágico, com citologia frequentemente negativa para células malignas claras.", "c": "Líquido viscoso tipo ''gelatina de morango'' (ácido hialurônico elevado).", "d": "Pus franco com bactérias intracelulares.", "e": "Líquido leitoso rico em linfócitos CD4."}, "answer": "b", "rationale": "O envolvimento pleural pelo Sarcoma de Kaposi no HIV é uma causa de derrame exsudativo e hemorrágico. O diagnóstico citológico é difícil porque as células fusiformes do sarcoma não se soltam facilmente para o líquido, muitas vezes exigindo biópsia ou visualização direta por VATS (lesões violáceas na pleura).", "option_rationales": {"a": "Incorreta. Tumores causam exsudatos.", "b": "Correta. Perfil do Kaposi visceral no tórax.", "c": "Incorreta. Descrição clássica do mesotelioma rico em ácido hialurônico.", "d": "Incorreta. Isso seria um empiema.", "e": "Incorreta. O quilotórax no HIV pode ocorrer por linfoma, mas o Kaposi é hemorrágico."}, "difficulty": "dificil", "tags": ["Pneumologia", "Infectologia", "HIV/AIDS", "Sarcoma de Kaposi"]}', 167, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 48 anos, etilista, apresenta quadro de dor abdominal em barra e dispneia. RX de tórax mostra derrame pleural à esquerda volumoso. Toracentese evidencia líquido sero-hemorrágico com amilase de 5.000 U/L (Amilase sérica 250 U/L). A tomografia de abdome confirma pseudocisto pancreático. Qual o mecanismo do derrame pleural neste caso?", "options": {"a": "Simpatia pleural à inflamação peripancreática.", "b": "Metástase pleural de câncer de pâncreas oculto.", "c": "Fístula Pancreato-Pleural através do hiato aórtico ou defeitos diafragmáticos.", "d": "Translocação bacteriana intestinal para a pleura.", "e": "Hipoalbuminemia por má absorção pancreática."}, "answer": "c", "rationale": "Em casos de pancreatite crônica com pseudocisto, pode haver a formação de uma fístula que leva o suco pancreático rico em amilase diretamente para o espaço pleural (geralmente o esquerdo). Diferente do derrame da pancreatite aguda (simpático), o derrame da fístula é volumoso, crônico e com níveis de amilase astronômicos.", "option_rationales": {"a": "Incorreta. O derrame simpático não atinge níveis tão altos de amilase (5.000 U/L).", "b": "Incorreta. O pseudocisto e a amilase indicam patologia benigna ductal pancreática.", "c": "Correta. Mecanismo de derrames pancreáticos volumosos recorrentes.", "d": "Incorreta. Não explica a amilase.", "e": "Incorreta. Causaria transudato bilateral."}, "difficulty": "media", "tags": ["Pneumologia", "Gastroenterologia", "Amilase Pleural", "Pancreatite"]}', 168, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 45 anos, em tratamento para Leucemia Mieloide Crônica (LMC) com o inibidor de tirosina quinase de segunda geração Dasatinibe, desenvolve dispneia progressiva e derrame pleural bilateral exsudativo. Qual é o mecanismo fisiopatológico mais aceito para este efeito colateral comum desta medicação?", "options": {"a": "Bloqueio do canal de cálcio pleural.", "b": "Toxicidade direta da medicação contra as células mesoteliais causando necrose.", "c": "Indução de Linfoma T secundário.", "d": "Inibição de quinases (como SRC) levando ao aumento da permeabilidade vascular e disfunção endotelial pleural.", "e": "Cardiotoxicidade com fração de ejeção de 20%."}, "answer": "d", "rationale": "O Dasatinibe é conhecido por causar derrame pleural em até 15-30% dos pacientes. O mecanismo envolve a inibição das quinases da família SRC, que regulam a permeabilidade das junções endoteliais. O tratamento consiste na suspensão temporária da droga ou redução da dose, associada ou não ao uso de corticoides.", "option_rationales": {"a": "Incorreta. Não é o mecanismo descrito.", "b": "Incorreta. Não há necrose mesotelial primária, mas sim aumento da permeabilidade.", "c": "Incorreta. Tratamento da leucemia não causa linfoma T de forma aguda como mecanismo de derrame.", "d": "Correta. Mecanismo de toxicidade endotelial farmacológica clássico.", "e": "Incorreta. O derrame pelo dasatinibe é exsudativo e ocorre mesmo com função cardíaca preservada."}, "difficulty": "media", "tags": ["Pneumologia", "Hematologia", "Dasatinibe", "Iatrogenia"]}', 169, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal diferença entre o ''Hemotórax'' e o ''Derrame Pleural Sero-hemorrágico'' na análise laboratorial?", "options": {"a": "Apenas a cor.", "b": "O Hemotórax é definido por um hematócrito do líquido pleural ≥ 50% do hematócrito do sangue periférico.", "c": "Ambas as alternativas B e C estão corretas e se complementam no raciocínio clínico.", "d": "O sero-hemorrágico é comum no câncer, enquanto o hemotórax é quase sempre traumático.", "e": "Não há diferença."}, "answer": "c", "rationale": "Esta é uma distinção técnica crucial. Pouco sangue (1-10 mL) já deixa o líquido vermelho (sero-hemorrágico). O hemotórax real exige uma concentração de hemácias significativa em relação ao sangue do paciente, mudando drasticamente a conduta (drenagem agressiva).", "option_rationales": {"a": "Incorreta.", "b": "Incorreta (sozinha).", "c": "Correta. Síntese do conhecimento técnico-clínico sobre sangue na pleura.", "d": "Incorreta (sozinha).", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Hematologia", "Hemotórax", "Critérios"]}', 170, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O ''Derrame Pleural Benigno do Asbesto'' (BAPE) é frequentemente asssintomático. No entanto, quando acompanhado de dor torácica persistente e evolução para espessamento pleural fibrótico difuso, pode mimetizar:", "options": {"a": "Mesotelioma Maligno.", "b": "Tuberculose Pleural.", "c": "Embolia pulmonar recorrente.", "d": "Sarcoidose estágio IV.", "e": "Pneumonia bacteriana."}, "answer": "a", "rationale": "A grande dificuldade diagnóstica do BAPE crônico e fibrótico é diferenciá-lo do mesotelioma em fase inicial. Ambas ocorrem em pacientes expostos ao asbesto e podem causar dor crônica. Muitas vezes apenas a videotoracoscopia com múltiplas biópsias profundas consegue selar o diagnóstico.", "option_rationales": {"a": "Correta. Principal desafio diagnóstico diferencial na medicina ocupacional torácica.", "b": "Incorreta. TB regride com tratamento; o BAPE fibrosa ou cicatriza sozinho.", "c": "Incorreta. TEP não causa espessamento pleural fibrótico difuso.", "d": "Incorreta. Sarcoidose IV é predominantemente fibrose parenquimatosa.", "e": "Incorreta. Quadro agudo com febre."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Derrame do Asbesto", "Mesotelioma"]}', 171, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A asbestose (fibrose intersticial pelo amianto) se associa ao mesotelioma de qual forma?", "options": {"a": "Apenas asbestose grave leva ao mesotelioma.", "b": "A asbestose é uma condição obrigatória para que o mesotelioma se desenvolva.", "c": "O mesotelioma pode ocorrer na ausência de asbestose radiológica ou clínica, bastando a exposição prévia às fibras de asbesto.", "d": "As duas doenças nunca ocorrem no mesmo paciente.", "e": "O tratamento da asbestose previne o mesotelioma."}, "answer": "c", "rationale": "O mesotelioma e a asbestose são doenças independentes causadas pelo mesmo agente. Um paciente pode ter mesotelioma sem ter fibrose pulmonar (asbestose) e vice-versa. O risco de mesotelioma está ligado à carga de exposição e ao tempo de latência.", "option_rationales": {"a": "Incorreta. Não há essa correlação linear direta.", "b": "Incorreta. São patologias distintas.", "c": "Correta. Dado importante para estadiamento e vigilância ocupacional.", "d": "Incorreta. Podem coexistir frequentemente.", "e": "Incorreta. Não existe tratamento curativo para asbestose que previna a transformação maligna pleural."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Asbesto", "Asbestose"]}', 172, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Síndrome das Unhas Amarelas'' (Yellow Nail Syndrome) associa derrame pleural linfocítico a linfedema de membros inferiores e unhas distróficas amareladas. Qual é a etiologia básica aceita para esta síndrome?", "options": {"a": "Deposição crônica de ferro ungueal.", "b": "Doença autoimune contra a queratina.", "c": "Infecção fúngica disseminada (onicomicose total).", "d": "Intoxicação por metais pesados (Cádmio).", "e": "Disfunção congênita ou adquirida na drenagem linfática sistêmica."}, "answer": "e", "rationale": "A síndrome decorre de uma hipoplasia ou obstrução funcional dos vasos linfáticos. O acúmulo de líquido linfático rico em proteínas na derme causa o linfedema e a alteração ungueal (crescimento lento e distrofia), além do derrame pleural por falha na absorção do líquido pelo sistema linfático pleural.", "option_rationales": {"a": "Incorreta. Sem relação.", "b": "Incorreta. Não é inflamatória autoimune por autoanticorpos.", "c": "Incorreta. As unhas são amarelas por estase linfática, não fungo primário (embora infecções secundárias possam ocorrer).", "d": "Incorreta. Não existe nexo causal estabelecido.", "e": "Correta. Fisiopatologia central da síndrome."}, "difficulty": "media", "tags": ["Pneumologia", "Linfologia", "Derrame Pleural", "Síndromes"]}', 173, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Tuberculose Pleural em pacientes com HIV/AIDS com contagem de CD4 < 100 células/mm³, qual a principal mudança observada no perfil do líquido pleural em comparação ao paciente imunocompetente?", "options": {"a": "Não existe TB pleural no HIV.", "b": "Ocorrência obrigatória de pneumotórax junto ao derrame.", "c": "O ADA cai para zero.", "d": "A baciloscopia (BAAR) e a cultura do líquido tornam-se POSITIVAS com mais frequência, devido à maior carga bacilar e menor resposta granulomatosa defensiva.", "e": "O derrame torna-se transudativo."}, "answer": "d", "rationale": "Em imunodeprimidos graves, a resposta de hipersensibilidade (granuloma) que normalmente mantém o líquido paucibacilar falha. Isso leva a uma disseminação hematogênica ou linfática mais intensa para a pleura, resultando em maior número de bacilos no líquido, facilitando o diagnóstico direto (BAAR/Cultura/TRM-TB).", "option_rationales": {"a": "Incorreta. É uma manifestação muito comum.", "b": "Incorreta. Não é regra.", "c": "Incorreta. O ADA pode continuar alto ou sofrer pouca variação.", "d": "Correta. Paradoxalmente, o diagnóstico microbiológico direto é mais fácil no HIV muito avançado.", "e": "Incorreta. Continua sendo exsudato inflamatório."}, "difficulty": "media", "tags": ["Pneumologia", "Infectologia", "HIV/AIDS", "Tuberculose"]}', 174, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A interrupção súbita do tratamento para derrame pleural por Artrite Reumatoide com doses altas de corticoide pode levar a:", "options": {"a": "Transformação em transudato.", "b": "Melhora do pH pleural.", "c": "Recorrência exuberante do derrame e risco de insuficiência adrenal secundária.", "d": "Cura da Artrite nas articulações.", "e": "Resolução completa do quadro."}, "answer": "c", "rationale": "Assim como em qualquer doença autoimune tratada com corticoides, o desmame deve ser gradual para evitar o efeito rebote da pleurite e para permitir a recuperação do eixo hipotálamo-hipófise-adrenal do paciente.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Preceito básico de manejo de corticoterapia sistêmica.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Reumatologia", "Corticosteroides", "Manejo"]}', 175, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Derrame Pleural por Lúpus Eritematoso Sistêmico (Pleurite Lúpica), a dosagem de anticorpos antinucleares (FAN) no líquido pleural apresenta qual utilidade clínica?", "options": {"a": "Substitui a necessidade de biópsia renal.", "b": "Baixa utilidade, pois o FAN pleural costuma ser negativo mesmo no lúpus.", "c": "Alta utilidade se o título for > 1:160, sendo muito específico para pleurite lúpica.", "d": "Inútil, pois é sempre idêntico ao título sérico e nunca ajuda no diagnóstico.", "e": "Indica obrigatoriamente insuficiência renal lúpica associada."}, "answer": "c", "rationale": "Diferentes estudos mostram que a dosagem de FAN no líquido pleural com títulos elevados (especialmente se maiores que os títulos séricos ou > 1:160) tem alto valor diagnóstico para pleurite lúpica. A detecção de células LE no líquido também é altamente específica.", "option_rationales": {"a": "Incorreta. Não substitui avaliação orgânica de outros sistemas.", "b": "Incorreta. Costuma ser positivo no lúpus serosítico.", "c": "Correta. Títulos altos no líquido favorecem o diagnóstico local de atividade lúpica.", "d": "Incorreta. Pode ajudar na diferenciação diagnóstica em casos de serosite isolada.", "e": "Incorreta. A serosite pode ocorrer independente da nefrite."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Lúpus", "FAN Pleural"]}', 176, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal complicação iatrogênica associada à toracocentese diagnóstica realizada sem auxílio de ultrassonografia, especialmente em derrames de pequeno volume?", "options": {"a": "Lipotímia vasovagal.", "b": "Edema pulmonar de reexpansão.", "c": "Pneumoniti por aspiração de líquido pleural.", "d": "Infecção do espaço pleural (Empiema iatrogênico).", "e": "Pneumotórax."}, "answer": "e", "rationale": "O pneumotórax é a complicação iatrogênica mais frequente da toracocentese ''cega''. O uso sistemático da ultrassonografia à beira do leito (POCUS) reduziu essa taxa de aproximadamente 10% para menos de 1-2% na prática clínica moderna.", "option_rationales": {"a": "Incorreta. É comum mas benigna, não relacionada à falta de US diretamente.", "b": "Incorreta. Isso ocorre apenas após drenagens volumosas (> 1,5L), não em toracocenteses diagnósticas pequenas.", "c": "Incorreta. Aspirar líquido não causa pneumonia por aspiração do próprio líquido na via aérea.", "d": "Incorreta. Raro se mantida técnica asséptica adequada.", "e": "Correta. A lesão pulmonar pela agulha é o risco principal sem guia de imagem."}, "difficulty": "facil", "tags": ["Pneumologia", "Procedimentos", "Toracocentese", "Segurança"]}', 177, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o manejo do cateter pleural de demora (IPC), qual a complicação tardia específica desse dispositivo que pode ocorrer em até 2 a 5% dos pacientes com Mesotelioma Maligno?", "options": {"a": "Quilotórax secundário.", "b": "Perfuração da veia cava superior.", "c": "Necrose de pele por tração.", "d": "Metástase no trajeto do cateter (Track metastasis).", "e": "Empiema bacteriano estéril."}, "answer": "d", "rationale": "Células malignas (especialmente do mesotelioma e do adenocarcinoma de pulmão) podem ''semear'' o trajeto por onde o cateter pleural de demora passa na parede torácica. Isso resulta em nódulos tumorais subcutâneos dolorosos no local do cateter, conhecidos como ''track metastasis''. Muitas vezes exige radioterapia local profilática ou paliativa.", "option_rationales": {"a": "Incorreta. Não há lesão do ducto torácico no trajeto subcutâneo do dreno.", "b": "Incorreta. Complicação de acesso venoso central, não de dreno pleural tunelizado.", "c": "Incorreta. Possível por erro de técnica, mas não é a complicação ''clássica'' tumoral descrita.", "d": "Correta. Fenômeno bem descrito em oncologia torácica.", "e": "Incorreta. O empiema purulento ocorre, mas não existe ''empiema estéril'' como diagnóstico de complicação do cateter."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Cateter Pleural", "Complicações"]}', 178, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista pesado apresenta derrame pleural volumoso recorrente. A citologia oncótica é positiva para carcinoma, mas o tipo celular é ''indiferenciado''. O painel de imuno-histoquímica no cell block mostra: CK7 (+), CK20 (-), TTF-1 (+), Napsina A (+). Qual o sítio primário mais provável?", "options": {"a": "Mama.", "b": "Rim (Carcinoma de células claras).", "c": "Cólon.", "d": "Pulmão (Adenocarcinoma).", "e": "Estômago."}, "answer": "d", "rationale": "O perfil CK7+ / CK20- associado à positividade de TTF-1 (Thyroid Transcription Factor-1) e Napsina A é altamente específico para o adenocarcinoma primário do pulmão. O TTF-1 positivo também pode ocorrer em tumores de tireoide, mas a Napsina A e o quadro clínico confirmam a origem pulmonar.", "option_rationales": {"a": "Incorreta. Mama costuma ser GATA3+ / Mamaglobina+.", "b": "Incorreta. Rim costuma ser PAX-8+ / RCC+.", "c": "Incorreta. Cólon costuma ser CK20+ / CK7- / CDX2+.", "d": "Correta. Algoritmo diagnóstico clássico da patologia pulmonar.", "e": "Incorreta. Estômago costuma ser CK7/CK20 variável."}, "difficulty": "media", "tags": ["Pneumologia", "Patologia", "Imuno-histoquímica", "Adenocarcinoma"]}', 179, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em relação à ''Síndrome de Meigs'', qual dos seguintes tumores ovarianos NÃO faz parte da definição clássica (que exige tumor benigno)?", "options": {"a": "Tecoma.", "b": "Fibroma de ovário.", "c": "Tumor de Brenner.", "d": "Cistoadenoma.", "e": "Adenocarcinoma de Ovário."}, "answer": "e", "rationale": "A Síndrome de Meigs clássica exige tumor benigno de ovário + ascite + derrame pleural, com resolução dos derrames após a cirurgia. O adenocarcinoma é maligno; sua tríade ascite/derrame seria a ''Pseudo-síndrome de Meigs'' ou simplesmente carcinomatose peritoneal/pleural.", "option_rationales": {"a": "Incorreta. É um tumor benigno estromal que causa a síndrome.", "b": "Incorreta. É o tumor mais clássico do Meigs.", "c": "Incorreta. Tumor fibroepitelial benigno associado ao Meigs.", "d": "Incorreta. Tumor epitelial benigno associado.", "e": "Correta. Tumor maligno que invalida a definição de Meigs puro."}, "difficulty": "media", "tags": ["Pneumologia", "Ginecologia", "Meigs", "Tumor Ovariano"]}', 180, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente jovem, sexo feminino, em tratamento de infertilidade com indutores de ovulação, apresenta dor abdominal, ascite e derrame pleural bilateral volumoso. Qual a fisiopatologia deste quadro (Síndrome de Hiperestimulação Ovariana - OHSS)?", "options": {"a": "Insuficiência cardíaca pós-parto.", "b": "Aumento maciço da permeabilidade vascular sistêmica mediado por VEGF e citocinas ovarianas, levando a extravasamento de líquido para terceiros espaços.", "c": "Torção de ovário purulenta.", "d": "Metástases de coriocarcinoma.", "e": "Infecção pélvica disseminada."}, "answer": "b", "rationale": "A OHSS é uma complicação grave da estimulação ovariana. O excesso de folículos produz mediadores (especialmente VEGF) que causam ''vazamento capilar'' sistêmico. O resultado é hemoconcentração, ascite e derrames pleurais (muitas vezes à direita ou bilateral).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Mecanismo molecular de permeabilidade endotelial.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Ginecologia", "OHSS", "VEGF"]}', 181, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Após uma cirurgia de Pneumonectomia Direta (retirada total do pulmão), o espaço vazio no hemitórax é preenchido gradualmente por líquido e ocorre o desvio do mediastino. Qual fenômeno é esperado no ''espaço pós-pneumonectomia'' em um paciente com evolução normal no primeiro mês?", "options": {"a": "O pulmão contralateral deve herniar para o lado operado imediatamente.", "b": "O mediastino deve ser empurrado para o lado oposto (contralateral) pelo líquido.", "c": "Indica-se a colocação de um dreno de tórax em selo d''água permanente.", "d": "Ocorre preenchimento por líquido (derramesinoso) e desvio do mediastino para o lado da cirurgia (ipsilateral).", "e": "O espaço deve ser preenchido por ar e permanecer vazio para sempre."}, "answer": "d", "rationale": "No pós-operatório estável de pneumonectomia, o hemitórax operado é preenchido por fluido sero-hemorrágico (derramamento pós-pneumonectomia) e o mediastino desvia-se para o lado operado (ipsilateral) à medida que o líquido é organizado e ocorre a redução volumétrica da cavidade. Se o mediastino desviar para o lado oposto, deve-se suspeitar de empiema ou hemorragia maciça.", "option_rationales": {"a": "Incorreta. A hérnia pulmonar contralateral leva tempo para ocorrer (meses/anos).", "b": "Incorreta. Indica tensão no espaço pleural (complicação).", "c": "Incorreta. A drenagem na pneumonectomia é feita com cautela ou nem é feita para evitar desvios súbitos do mediastino.", "d": "Correta. Evolução radiológica e fisiológica esperada.", "e": "Incorreta. O ar seria sinal de fístula ou erro de técnica."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cirurgia Torácica", "Pneumonectomia", "Fisiologia"]}', 182, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A fístula ''Gastropleural'' é uma complicação rara após qual cirurgia bariátrica, manifestando-se como derrame pleural purulento persistente?", "options": {"a": "Balão introgástrico.", "b": "Gastrectomia Vertical (Sleeve) ou Bypass Gástrico em Y-de-Roux.", "c": "Colecistectomia.", "d": "Lipoaspiração abdominal.", "e": "Apenas em cirurgias de hérnia inguinal."}, "answer": "b", "rationale": "A fístula do ângulo de His (em cirurgias de Sleeve) pode levar à formação de abscesso subfrênico que erode o diafragma e comunica o estômago com o espaço pleural, causando empiema de difícil manejo que exige drenagem pleural e abdominal simultâneas e correção da fístula digestiva.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação cirúrgica moderna relevante.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Bariátrica", "Fístula Gastropleural", "Empiema"]}', 183, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A maioria dos derrames pleurais associados ao Tromboembolismo Pulmonar (TEP) são pequenos e localizados unilateralmente. Qual a característica citológica e bioquímica MAIS FREQUENTE nesses derrames?", "options": {"a": "Exsudato com glicose zero (consumida pelo infarto).", "b": "Transudato com predominância de células mesoteliais.", "c": "Exsudato tipicamente hemorrágico e frequentemente eosinofílico.", "d": "Empiema purulento por infarto pulmonar infectado.", "e": "Líquido leitoso com triglicerídeos elevados."}, "answer": "c", "rationale": "No TEP, o derrame ocorre por aumento da permeabilidade capilar após a isquemia e liberação de mediadores inflamatórios. Aproximadamente 75-80% são exsudatos, frequentemente hemorrágicos (pela isquemia/infarto) e eosinofílicos (pela presença de sangue no espaço pleural).", "option_rationales": {"a": "Incorreta. A glicose costuma ser normal no TEP.", "b": "Incorreta. Apenas 20% do TEP cursa com transudato.", "c": "Correta. Perfil clássico do TEP na pleura.", "d": "Incorreta. O infarto pulmonar pode infectar (pneumonia), mas não é o padrão do TEP agudo.", "e": "Incorreta. TEP não causa quilotórax."}, "difficulty": "media", "tags": ["Pneumologia", "TEP", "Derrame Pleural", "Eosinofilia"]}', 184, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Considere um paciente com Cirrose Hepática e ascite volumosa que desenvolve derrame pleural à direita (Hidrotórax Hepático). Sobre esta condição, assinale a afirmativa correta.", "options": {"a": "A pleurodese química tem alta taxa de sucesso mesmo na presença de ascite descontrolada.", "b": "A toracentese repetida é o tratamento de escolha a longo prazo.", "c": "O mecanismo fisiopatológico principal é a hipoalbuminemia severa isolada.", "d": "O líquido pleural costuma ser um exsudato devido à translocação bacteriana.", "e": "A drenagem por tubo de tórax é frequentemente contraindicada devido ao risco de depleção proteica e eletrolítica massiva."}, "answer": "e", "rationale": "No hidrotórax hepático, a drenagem pleural com dreno tubular deve ser evitada ao máximo, pois o líquido pleural é contínuo com a ascite através de defeitos diafragmáticos. A drenagem leva à perda rápida de proteínas, eletrólitos e fluidos, podendo causar insuficiência renal aguda e desnutrição severa.", "option_rationales": {"a": "Incorreta. A ascite dificulta a sínfise das pleuras, tornando a pleurodese ineficaz.", "b": "Incorreta. Toracocenteses repetidas aumentam o risco de infecção e empiema.", "c": "Incorreta. O mecanismo principal é a passagem de ascite pelos poros diafragmáticos por pressão negativa intratorácica.", "d": "Incorreta. O líquido é classicamente um transudato.", "e": "Correta. Drenagem tubular em cirróticos com ascite é perigosa e deve ser evitada."}, "difficulty": "dificil", "tags": ["Pneumologia", "Gastroenterologia", "Hidrotórax Hepático", "Cirrose"]}', 185, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico apresenta derrame pleural à direita. A análise mostra: pH 7,42, Glicose 90 mg/dL, Proteína 2,8 g/dL (Sérica 6,5 g/dL) e LDH 180 U/L (Sérico 400 U/L). De acordo com os critérios de Light, este derrame é classificado como:", "options": {"a": "Líquido Borderline.", "b": "Exsudato.", "c": "Inconclusivo.", "d": "Empiema.", "e": "Transudato."}, "answer": "e", "rationale": "Cálculo do Light: 1) Prot Pleural/Prot Sérica = 2,8/6,5 = 0,43 (Corte > 0,5); 2) LDH Pleural/LDH Sérico = 180/400 = 0,45 (Corte > 0,6); 3) LDH Pleural = 180 (Corte > 2/3 do limite superior do soro, assumindo 400 como normal, 180 não atinge 266). Como nenhum critério é preenchido, o líquido é um transudato.", "option_rationales": {"a": "Incorreta. Não existe este termo na classificação de Light.", "b": "Incorreta. Precisaria de pelo menos um critério positivo.", "c": "Incorreta. Os cálculos são claros.", "d": "Incorreta. Exige critérios inflamatórios severos.", "e": "Correta. Classificação clássica pelos valores apresentados."}, "difficulty": "facil", "tags": ["Pneumologia", "Líquido Pleural", "Critérios de Light"]}', 186, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 80 anos desenvolve derrame pleural volumoso bilateral e anasarca. A análise revela um transudato. O TSH, a função renal e a função hepática são normais. A dosagem de albumina sérica é de 1,8 g/dL (muito baixa). O paciente é desdentado e mora sozinho. Qual o provável diagnóstico nutricional associado ao derrame?", "options": {"a": "Síndrome Paraneoplásica consumptiva.", "b": "Beribéri (Deficiência de Tiamina) com ICC de alto débito.", "c": "Kwashiorkor do idoso (Desnutrição proteica grave).", "d": "Síndrome de Má Absorção por doença celíaca tardia.", "e": "Escorbuto por deficiência de vitamina C."}, "answer": "c", "rationale": "A hipoalbuminemia grave (< 2,0 g/dL) pode levar à formação de transudatos pleurais bilaterais por redução da pressão oncótica plasmática. Em idosos com baixa ingesta proteica (hipoproteinemia), este quadro de anasarca e derrame é uma manifestação de desnutrição proteica severa.", "option_rationales": {"a": "Incorreta. Neoplasias dariam mais comumente exsudatos e não necessariamente hipoalbuminemia tão isolada e grave sem outros sinais.", "b": "Incorreta. O Beribéri causa ICC, o que daria derrame, mas a albumina de 1,8 aponta para causa oncótica primária (nutricional).", "c": "Correta. Causa de transudato por baixa pressão oncótica.", "d": "Incorreta. Menos provável no contexto social descrito.", "e": "Incorreta. Escorbuto causa sangramentos e alterações de pele, não derrame pleural por hipoproteinemia isolada."}, "difficulty": "media", "tags": ["Pneumologia", "Nutrologia", "Geriatria", "Hipoalbuminemia"]}', 187, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A síndrome de ''Mounier-Kuhn'' (Traqueobroncomegalia) associa-se a infecções respiratórias recorrentes. Qual a sua relação potencial com patologias pleurais?", "options": {"a": "Pode levar a episódios repetidos de derrame parapneumônico e empiema devido à bronquiectasia grave e falha no clearance de secreções.", "b": "Causa mesotelioma precocemente.", "c": "Não tem nenhuma relação.", "d": "Leva à calcificação do diafragma.", "e": "É a principal causa de quilotórax."}, "answer": "a", "rationale": "A dilatação excessiva da traqueia e brônquios (por atrofia de fibras elásticas) causa estase de secreção e bronquiectasias. Isso predispõe a pneumonias graves recorrentes, que por sua vez podem complicar com derrames pleurais e empiemas de repetição.", "option_rationales": {"a": "Correta. Nexo clínico via complicações infecciosas pulmonares.", "b": "Incorreta. Mesotelioma é ambiental (asbesto).", "c": "Incorreta. Doenças das vias aéreas impactam o espaço pleural via infecção.", "d": "Incorreta.", "e": "Incorreta. Quilotórax é doença linfática."}, "difficulty": "media", "tags": ["Pneumologia", "Vias Aéreas", "Empiema", "Bronquiectasia"]}', 188, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A coloração de Gram no líquido pleural tem sensibilidade moderada, mas alta especificidade. Se o Gram for positivo em um paciente com derrame parapneumônico, mas as culturas forem negativas após 72h, qual a interpretação clínica?", "options": {"a": "Trata-se de Tuberculose disfarçada de bactéria.", "b": "O dreno de tórax pode ser retirado imediatamente.", "c": "O Gram foi um falso-positivo por contaminação do reagente.", "d": "As bactérias estão mortas ou o crescimento foi inibido por antibióticos prévios, mas o derrame ainda deve ser tratado como empiema/complicado.", "e": "A infecção é viral."}, "answer": "d", "rationale": "Gram positivo = Germe visualizado. Se a cultura for negativa, isso frequentemente decorre do fato de o paciente já estar recebendo antibióticos que ''esterilizam'' a amostra mas as carcaças bacterianas ou germes não viáveis persistem. A drenagem e o tratamento agressivo continuam indicados.", "option_rationales": {"a": "Incorreta. TB não aparece no Gram comum (precisa de Ziehl).", "b": "Incorreta. Se houve germe no espaço pleural, a drenagem é necessária até resolução clínica total.", "c": "Incorreta. Menos provável no cenário clínico.", "d": "Correta. Padrão comum no empiema ''descapitados'' por antibiótico.", "e": "Incorreta. Vírus não aparecem no Gram."}, "difficulty": "facil", "tags": ["Pneumologia", "Laboratório", "Microbiologia", "Empiema"]}', 189, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de NT-proBNP no líquido pleural pode ser útil em situações específicas de diagnóstico desafiador. Qual o principal cenário onde este exame é recomendado?", "options": {"a": "Prever a resposta à pleurodese no câncer de pulmão.", "b": "Confirmar Tuberculose Pleural em pacientes anérgicos.", "c": "Monitorar a eficácia da antibioticoterapia no empiema.", "d": "Distinguir Transudato Cardíaco de Exsudato Maligno quando os critérios de Light são ambíguos.", "e": "Identificar pancreatite necrotizante precoce."}, "answer": "d", "rationale": "O NT-proBNP pleural (> 1500 pg/mL) é um excelente marcador de insuficiência cardíaca. Ele é útil exatamente quando os critérios de Light classificam o derrame como exsudato (falso-positivo), ajudando a evitar investigações invasivas desnecessárias para câncer ou TB em pacientes com disfunção miocárdica.", "option_rationales": {"a": "Incorreta. Não é marcador prognóstico de pleurodese.", "b": "Incorreta. NT-proBNP não tem relação com infecções granulomatosas.", "c": "Incorreta. Não é marcador de infecção ou resposta inflamatória aguda bacteriana.", "d": "Correta. Auxilia na diferenciação entre causa cardíaca e outras causas em casos borderline.", "e": "Incorreta. Para pâncreas usamos amilase e lipase."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cardiologia", "Biomarcadores", "ICC"]}', 190, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A pleurodese com talco pode ser realizada via ''Talc Slurry'' (instilação de suspensão líquida pelo dreno) ou ''Talc Poudrage'' (insuflação de talco seco durante videotoracoscopia). Sobre a eficácia, qual a evidência trazida pelos grandes ensaios clínicos modernos?", "options": {"a": "O talco insuflado (poudrage) apresenta maior taxa de sucesso na sínfise pleural, especialmente em pacientes com câncer de mama ou pulmão.", "b": "Ambos têm eficácia idêntica, sendo o Slurry preferido por ser mais barato e menos invasivo.", "c": "O Slurry é mais seguro por não causar reação inflamatória sistêmica.", "d": "A pleurodese química não deve mais ser feita, sendo substituída por cateteres de demora em 100% dos casos.", "e": "O talco líquido (slurry) é infinitamente superior em todos os tipos de câncer."}, "answer": "a", "rationale": "Embora o Slurry seja eficaz e prático, grandes meta-análises sugerem que o ''Talc Poudrage'' (via VATS) garante uma distribuição mais uniforme do talco em toda a superfície pleural, resultando em taxas de sucesso ligeiramente superiores em grupos específicos e menor necessidade de reintervenção em oncologia.", "option_rationales": {"a": "Correta. Superioridade na uniformidade da sínfise.", "b": "Incorreta. Existe uma tendência estatística de superioridade do Poudrage em estudos maiores.", "c": "Incorreta. Ambos podem causar SRIS se as partículas de talco forem pequenas demais (não graduadas).", "d": "Incorreta. A pleurodese ainda é padrão-ouro para muitos pacientes com pulmão reexpansível.", "e": "Incorreta. Slurry é menos distribuído que o poudrage."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Pleurodese", "Evidências"]}', 191, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 45 anos, submetido a cirurgia de revascularização do miocárdio há 3 semanas, retorna ao pronto-socorro com febre (38,2°C), dor torácica pleurítica e dispneia. Ao exame, percebe-se atrito pericárdico à ausculta. Radiografia de tórax revela derrame pleural bilateral e aumento da silhueta cardíaca. A análise do líquido pleural mostra um exsudato hemorrágico com predomínio de linfócitos. Qual o diagnóstico e o tratamento de escolha?", "options": {"a": "Pneumonia nosocomial tardia; piperacilina-tazobactam.", "b": "Empiema pleural bilateral por contaminação intraoperatória; drenagem tubular bilateral.", "c": "Síndrome de Post-Pericardiotomia (Síndrome de Dressler); anti-inflamatórios (AINEs) e colchicina.", "d": "Embolia pulmonar pós-operatória; anticoagulação plena.", "e": "Tamponamento cardíaco traumático; pericardiocentese imediata e drenagem pleural."}, "answer": "c", "rationale": "A Síndrome de Lesão Pós-Cardíaca (que inclui a síndrome pós-pericardiotomia) é um processo autoimune que ocorre de semanas a meses após cirurgias cardíacas, infartos ou traumas. Caracteriza-se por pleuropericardite, febre e derrames exsudativos (muitas vezes hemorrágicos ou eosinofílicos). O tratamento baseia-se em anti-inflamatórios (Aspirina ou Ibuprofeno) e Colchicina para prevenir recorrências.", "option_rationales": {"a": "Incorreta. A febre no pós-operatório tardio associada a serosites é mais comumente autoimune do que pneumonia bacteriana sem infiltrado.", "b": "Incorreta. Empiema bilateral seria extremamente raro e o líquido seria purulento/neutrofílico, não linfocítico-hemorrágico.", "c": "Correta. Diagnóstico clássico do pós-operatório de CRM.", "d": "Incorreta. O quadro de atrito pericárdico e a temporalidade pós-cirúrgica apontam mais para serosite autoimune.", "e": "Incorreta. O aumento da silhueta sugere derrame, mas não há sinais clínicos de choque obstrutivo (tamponamento)."}, "difficulty": "media", "tags": ["Pneumologia", "Cardiologia", "Síndrome de Dressler", "Derrame Pleural"]}', 192, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente feminina, 32 anos, apresenta episódios recorrentes de pneumotórax e derrame pleural quiloso (Quilotórax). A tomografia de tórax revela múltiplos cistos aéreos de paredes finas distribuídos difusamente pelo parênquima pulmonar. Qual o diagnóstico mais provável?", "options": {"a": "Histiocitose de Células de Langerhans.", "b": "Fibrose Cística.", "c": "Enfisema pan-acinar por deficiência de alfa-1 antitripsina.", "d": "Linfangioleiomiomatose (LAM).", "e": "Pneumonia Intersticial Linfocítica."}, "answer": "d", "rationale": "A LAM é uma doença rara que acomete quase exclusivamente mulheres em idade fértil. Caracteriza-se pela proliferação de células musculares lisas atípicas (células LAM) que obstruem vias aéreas (causando cistos/pneumotórax) e vasos linfáticos (causando quilotórax).", "option_rationales": {"a": "Incorreta. Causa pneumotórax e cistos (especialmente em ápices e tabagistas), mas não quilotórax.", "b": "Incorreta. Doença bronquiolar supurativa crônica, não cística/quilotórax primário.", "c": "Incorreta. Enfisema não cursa com quilotórax.", "d": "Correta. Associação clássica: mulher jovem + cistos + quilotórax.", "e": "Incorreta. Associada a doenças autoimunes (Sjögren), mas o quilotórax não é típico."}, "difficulty": "media", "tags": ["Pneumologia", "LAM", "Quilotórax", "Mulher"]}', 193, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em relação à ventilação mecânica com pressão positiva (PEEP), qual o efeito esperado na detecção do líquido pleural por radiografia de tórax?", "options": {"a": "Sempre causa pneumotórax hipertensivo em derrames pequenos.", "b": "Dificulta a realização de ultrassom.", "c": "O PEEP alto pode ''esconder'' o derrame pleural mascarando a opacidade pelo aumento da aeração do parênquima ou por redistribuição compressiva do líquido.", "d": "Aumenta a facilidade de ver pequenas quantidades de líquido.", "e": "Causa desaparecimento total do líquido por evaporação interna."}, "answer": "c", "rationale": "A pressão positiva reexpande áreas de atelectasia e empurra o líquido pleural para posições mais inferiores ou laterais, o que pode reduzir o ''velamento'' clássico na radiografia e fazer com que o volume do derrame pareça menor do que realmente é.", "option_rationales": {"a": "Incorreta. Risco de barotrauma existe, mas não é regra absoluta.", "b": "Incorreta. O ultrassom continua sendo muito sensível independentemente do PEEP.", "c": "Correta. Desafio radiológico no paciente crítico em UTI.", "d": "Incorreta. Pelo contrário, tende a mascarar.", "e": "Incorreta. Explicação absurda."}, "difficulty": "media", "tags": ["Pneumologia", "Terapia Intensiva", "Radiologia", "UTI"]}', 194, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição da adenosina deaminase (ADA) no líquido pleural tem excelente sensibilidade para Tuberculose. Entretanto, qual é a principal causa de FALSO-POSITIVO (ADA elevado sem TB) em pacientes idosos com derrame exsudativo?", "options": {"a": "Insuficiência Cardíaca.", "b": "Atelectasia pós-cirúrgica.", "c": "Empiema e Artrite Reumatoide.", "d": "Urinotórax.", "e": "Derrame por Cirrose Hepática."}, "answer": "c", "rationale": "O ADA é um marcador de ativação de linfócitos T. Assim, qualquer processo inflamatório muito intenso pode elevar o ADA. No empiema (especialmente se houver linfócitos ou lise celular), no linfoma e na Artrite Reumatoide, o ADA pode ultrapassar 40-70 U/L, gerando confusão com TB. No entanto, o empiema é neutrofílico, o que ajuda na diferenciação.", "option_rationales": {"a": "Incorreta. Transudatos têm ADA baixo.", "b": "Incorreta. ADA baixo.", "c": "Correta. Principais causas de falso-positivos elevados.", "d": "Incorreta. Transudatos e sem inflamação aguda mediada por T.", "e": "Incorreta. Transudatos têm ADA baixo."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Laboratório", "ADA"]}', 195, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente de 4 anos com quadro de febre alta, dispneia e prostração. Radiografia de tórax mostra derrame pleural à direita ocupando 50% do hemitórax. Realizada toracentese que evidencia líquido turvo com pH de 7,05, glicose de 28 mg/dL e LDH de 2.200 U/L. O patógeno MAIS PROVÁVEL de ser isolado neste empiema pediátrico é:", "options": {"a": "Mycoplasma pneumoniae.", "b": "Staphylococcus aureus.", "c": "Haemophilus influenzae tipo b.", "d": "Klebsiella pneumoniae.", "e": "Streptococcus pneumoniae."}, "answer": "e", "rationale": "O Pneumococo (Streptococcus pneumoniae) continua sendo a causa número 1 de derrame pleural parapneumônico e empiema em crianças, mesmo após a introdução das vacinas conjugadas (devido ao escape de alguns sorotipos).", "option_rationales": {"a": "Incorreta. Mycoplasma raramente causa empiemas purulentos volumosos.", "b": "Incorreta. O S. aureus é comum e grave, mas o pneumococo ainda lidera as estatísticas gerais.", "c": "Incorreta. Tornou-se raro após a vacinação extensiva.", "d": "Incorreta. Raro em crianças hígidas; mais associado a etilistas e diabéticos adultos.", "e": "Correta. Principal etiologia na pediatria."}, "difficulty": "facil", "tags": ["Pneumologia", "Pediatria", "Empiema", "Infectologia"]}', 196, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual medicação, muito utilizada no tratamento de infecção urinária recorrente, é uma causa clássica e bem conhecida de derrame pleural exsudativo com eosinofilia e infiltrado pulmonar intersticial por mecanismo de hipersensibilidade?", "options": {"a": "Ciprofloxacino.", "b": "Fosfomicina.", "c": "Nitrofurantoína.", "d": "Ceftriaxona.", "e": "Norfloxacino."}, "answer": "c", "rationale": "A nitrofurantoína pode causar toxicidade pulmonar aguda ou crônica. A forma aguda é uma reação de hipersensibilidade caracterizada por febre, calafrios, tosse, eosinofilia periférica e derrame pleural eosinofílico. A suspensão da droga costuma levar à rápida resolução do quadro.", "option_rationales": {"a": "Incorreta. Quinolonas raramente causam tal reação.", "b": "Incorreta. Medicação segura do ponto de vista pulmonar.", "c": "Correta. Causa clássica de toxicidade pleuropulmonar eosinofílica.", "d": "Incorreta. Não apresenta este padrão de toxicidade.", "e": "Incorreta. Não associada tipicamente a este quadro."}, "difficulty": "facil", "tags": ["Pneumologia", "Farmacodinâmica", "Derrame Pleural Iatrogênico", "Nitrofurantoína"]}', 197, 'draft');
